"""D5/D9 third-party reference registry and composition.

Native port of the extension point Go added to
internal/integrations/render.go (ThirdPartyReference,
UpsertThirdPartyReference, ApplyThirdPartyReferences,
NormalizeThirdPartyContent, ResolveThirdPartySkillDestination) and
internal/integrations/plan.go (BuildPlans reapplying references after
Render).

Why this exists (D9, emenda pós-implementação do ADR): D5 says the
catalog agent's rendered file receives a reference line to a third-party
skill, between dedicated marker comments. But that file is REGENERATED by
trackfw.integrations.catalog.plan_deployments every time `trackfw agents
update` runs — without persisting the reference somewhere and having
plan_deployments reproduce it after every render, the regenerated content
would be missing the block and the attachment would be read as drift
(state "modified"), exactly what D5 exists to prevent.

Deliberately a THIRD schema, separate from provenance.py's
thirdparty-provenance.json (see the ADR D9 rationale): provenance is
keyed by the third-party artifact's OWN destination and is the object
whose integrity `thirdparty_artifact_has_provenance` checks; references
are keyed by target+catalog-agent-item and are read on the render path.
Fusing the two would force the render path to invert-index the whole
provenance file on every render, and would make attaching/detaching a
reference mutate the audit record for a reason that has nothing to do
with audit.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from .quarantine import _atomic_write

# Bump only alongside a migration path.
REFERENCES_SCHEMA_VERSION = 1

# Composition markers (D5), dedicated and distinct from any auxiliary
# rules-file markers elsewhere in this codebase — mirrors the idempotent
# marker-replace pattern already used for rules injection.
THIRDPARTY_REF_START = "<!-- trackfw:thirdparty-skills:start -->"
THIRDPARTY_REF_END = "<!-- trackfw:thirdparty-skills:end -->"


def references_path(root) -> Path:
    return Path(root) / ".trackfw" / "thirdparty-references.json"


def _load_registry(root) -> dict[str, Any]:
    filename = references_path(root)
    try:
        raw = filename.read_bytes()
    except FileNotFoundError:
        return {"schema_version": REFERENCES_SCHEMA_VERSION, "entries": {}}
    except OSError as error:
        raise RuntimeError(f"read thirdparty reference registry: {error}") from error
    try:
        registry = json.loads(raw)
    except json.JSONDecodeError as error:
        raise RuntimeError(f"decode thirdparty reference registry: {error}") from error
    if registry.get("schema_version") != REFERENCES_SCHEMA_VERSION:
        raise RuntimeError(
            f"unsupported thirdparty reference registry schema {registry.get('schema_version')}"
        )
    if not isinstance(registry.get("entries"), dict):
        registry["entries"] = {}
    return registry


def _write_registry(root, registry: dict[str, Any]) -> None:
    registry = dict(registry)
    registry["schema_version"] = REFERENCES_SCHEMA_VERSION
    registry.setdefault("entries", {})
    data = (json.dumps(registry, indent=2, ensure_ascii=False) + "\n").encode("utf-8")
    try:
        _atomic_write(references_path(root), data, 0o600)
    except OSError as error:
        raise RuntimeError(f"write thirdparty reference registry: {error}") from error


def upsert_third_party_reference(root, target_id: str, agent_item_id: str, ref: dict[str, str]) -> None:
    """Records (or replaces, keyed by ref['slug']) a reference from the
    rendered catalog agent artifact (target_id, agent_item_id) to a
    third-party skill, and persists it under root (project root — D4).
    Idempotent: calling it twice with the same slug replaces the prior
    entry instead of duplicating it.

    ref is expected to have keys "slug", "destination", "url"."""
    registry = _load_registry(root)
    key = f"{target_id}/{agent_item_id}"
    refs: list[dict[str, str]] = registry["entries"].get(key, [])
    replaced = False
    for index, existing in enumerate(refs):
        if existing.get("slug") == ref.get("slug"):
            refs[index] = dict(ref)
            replaced = True
            break
    if not replaced:
        refs.append(dict(ref))
    refs.sort(key=lambda item: item.get("slug", ""))
    registry["entries"][key] = refs
    _write_registry(root, registry)


def apply_third_party_references(root, content: bytes, target_id: str, agent_item_id: str) -> bytes:
    """Injects or updates the third-party reference block in content for
    (target_id, agent_item_id), based on entries persisted by
    upsert_third_party_reference. When root is falsy or there are no
    entries for this key, content is returned byte-for-byte unchanged —
    the guarantee that every agent artifact which never received a
    third-party attachment renders exactly as it did before D5 was
    introduced, by construction.

    content is expected to already be normalize_markdown's output (a
    single trailing "\\n", no surrounding extra whitespace) — true for
    every caller, since this is only invoked right after render()
    produces the catalog agent's markdown representation
    (trackfw.integrations.catalog.plan_deployments)."""
    if not root:
        return content
    registry = _load_registry(root)
    refs = registry["entries"].get(f"{target_id}/{agent_item_id}", [])
    if not refs:
        return content

    lines = [THIRDPARTY_REF_START]
    for ref in refs:
        lines.append(f'- Third-party skill "{ref["slug"]}": {ref["destination"]} (source: {ref["url"]})')
    lines.append(THIRDPARTY_REF_END)
    block = "\n".join(lines)

    text = content.decode("utf-8")
    start = text.find(THIRDPARTY_REF_START)
    if start == -1:
        if not text.endswith("\n"):
            text += "\n"
        text += "\n" + block + "\n"
        return text.encode("utf-8")
    # Search for the end marker starting at start, not from the beginning
    # of text (hefesto-tf finding, ML-4C): searching the whole text could
    # find an END marker that appears BEFORE start, producing end < start
    # and silently corrupting the composed output. Anchoring the search at
    # start makes that impossible: end is either -1 or >= start.
    rel_end = text[start:].find(THIRDPARTY_REF_END)
    if rel_end == -1:
        # Malformed (start without end): append a fresh block rather than
        # guess at repair.
        text += "\n" + block + "\n"
        return text.encode("utf-8")
    end = start + rel_end
    new_text = text[:start] + block + text[end + len(THIRDPARTY_REF_END):]
    return (new_text.rstrip("\n") + "\n").encode("utf-8")


def normalize_third_party_content(content: bytes) -> bytes:
    """Applies the same normalization render() uses for managed catalog
    skill content (strip + single trailing newline) to raw third-party
    bytes before they are written through IntegrationManager.install, so
    third-party artifacts are stored with the same on-disk convention as
    catalog artifacts. Lazily imports trackfw.integrations.renderers to
    avoid a module-load-time cycle with
    trackfw.integrations.catalog (which imports this module to reapply
    references after render — see the module docstring's D9 rationale)."""
    from trackfw.integrations.renderers import normalize_markdown

    return normalize_markdown(content.decode("utf-8")).encode("utf-8")


def _truncate_before_id_segment(template: str) -> str:
    """Drops the "{{id}}"-bearing path segment and everything after it,
    returning the shared parent directory. Deliberately replicated here
    rather than imported from trackfw.integrations.catalog's
    _truncate_before_id_segment (which is private/underscore-prefixed and
    importing it would risk a load-time cycle the other direction:
    catalog.py already imports this module at module scope for
    apply_third_party_references) — mirrors the "replicated here rather
    than imported" pattern already used by quarantine.py/provenance.py
    for _atomic_write and by markers.py's checksum() for Go's
    contentHash."""
    segments = template.split("/")
    for index, segment in enumerate(segments):
        if "{{id}}" in segment:
            return "/".join(segments[:index])
    return template


def resolve_third_party_skill_destination(
    catalog: dict[str, Any], target_id: str, scope: str, slug: str
) -> tuple[str, str, str]:
    """Computes where a third-party artifact's content should live for
    (target_id, scope), per D5: the shared parent directory of the
    target's own canonical project/global Skills install path template
    (e.g. ".claude/skills/trackfw-{{id}}/SKILL.md" truncates to
    ".claude/skills"), followed by "/thirdparty/<slug>.md". The directory
    always comes from the catalog's own path template — never a
    hardcoded ".claude" — so every target the catalog declares a Skills
    capability for is supported without per-target special-casing.

    Returns (destination, surface_id, representation) — representation is
    an addition over the Go signature (which only returns destination and
    surfaceID): trackfw.integrations.manager.IntegrationManager.inspect
    requires plan["representation"] to be present (unlike Go's
    PlannedArtifact, which has no Representation field at all), so the
    caller (trackfw.commands.thirdparty) needs it to build a valid
    synthetic plan for the third-party skill artifact."""
    target = next((entry for entry in catalog["targets"] if entry["id"] == target_id), None)
    if target is None:
        raise ValueError(f"unknown target {target_id!r}")

    surfaces = target["surfaces"]
    compatible = [s for s in surfaces if s["capabilities"]["skills"]["support_level"] != "unsupported"]
    surface = None
    for candidate in surfaces:
        level = candidate["capabilities"]["skills"]["support_level"]
        if level not in {"legacy", "unsupported"}:
            surface = candidate
            break
    if surface is None:
        if not compatible:
            raise ValueError(f"target {target_id} has no supported skills surface")
        surface = compatible[0]

    install_path = next(
        (entry for entry in surface["paths"]["skills"] if entry["scope"] == scope), None
    )
    if install_path is None:
        raise ValueError(f"target {target_id} surface {surface['id']} has no {scope} skills path")

    base_dir = _truncate_before_id_segment(install_path["path"])
    representation = surface["capabilities"]["skills"]["representation"]
    return f"{base_dir}/thirdparty/{slug}.md", surface["id"], representation
